; Quest for Glory I VGA (SCI1.1), Korean UTF-8 translation: GAMES\QFG1KO with
; RESOURCE.MSG + MESSAGE.MAP, the loose .MSG patches and SCI-KO.STR
; (language=ko, text_encoding=utf8).
;
; One face and size per font id, chosen by the game font's height and how
; decorated it is. A line is the game height x 2 hi-res px; each face is baked
; in a cell two px smaller (the leading), on one baseline, ink clipped to the
; cell. Baked by tools/korean/bake-qfg1-fonts.sh from the characters the
; translation uses; fonts 0, 3, 4 use NGOTB16.SVF, the shared NanumGothic Bold
; 16 px KS X 1001 face of the same cell and baseline (its glyphs are the ones
; the QFG1 subset had, byte for byte).
;
;   id    game px  look                               line  face
;   999       8     tiny, plain                         16   NGOTB14  NanumGothic-Bold 14
;   0,3,4     9     plain: status bar, dialogue, UI     18   NGOTB16  NanumGothic-Bold 16
;   2107     10     calligraphic                        20   GBATB18A GowunBatang-Bold 18
;   1        12     plain, larger                       24   NGOTB22  NanumGothic-Bold 22
;   300      12     calligraphic: message boxes         24   GBATB21  GowunBatang-Bold 21
;   123      15     blackletter display: titles         30   BHSAN28  BlackHanSans 28 (Hangul)
;                                                             COUSB24  Coustard-Black 24 (Latin)
;
; True colour only (the faces are 2 bpp). A render_target=clut8 screen
; needs 1 bpp faces, which this map does not provide yet.
[map]
version=2

[render]
scale=2
blend=auto

[fonts]
g14=NGOTB14.SVF
g16=NGOTB16.SVF
b18=GBATB18A.SVF
g22=NGOTB22.SVF
b22=GBATB21.SVF
t28=BHSAN28.SVF
l28=COUSB24.SVF

[font]
face=g16
cell=glyph
size=16
missing=u+25a1
align=cell
range.basic-latin=same
advance.basic-latin=font

[font.999]
face=g14
size=14

[font.0]
face=g16

[font.3]
face=g16

[font.4]
face=g16

[font.2107]
face=b18
size=18

[font.1]
face=g22
size=22

[font.300]
face=b22
size=22

[font.123]
face=t28
size=28
range.basic-latin=l28
missing=off
